```python
from collections import deque
import math
import random

# ACTION constants
ACTION_NOOP = 0
ACTION_LEFT = 1
ACTION_RIGHT = 2
ACTION_UP = 3
ACTION_DOWN = 4
ACTION_DO = 5
ACTION_SLEEP = 6
ACTION_PLACE_STONE = 7
ACTION_PLACE_TABLE = 8
ACTION_PLACE_FURNACE = 9
ACTION_PLACE_PLANT = 10
ACTION_MAKE_WOOD_PICK = 11
ACTION_MAKE_STONE_PICK = 12
ACTION_MAKE_IRON_PICK = 13
ACTION_MAKE_WOOD_SWORD = 14
ACTION_MAKE_STONE_SWORD = 15
ACTION_MAKE_IRON_SWORD = 16

# direction helpers
DIRS = {
    1: (-1, 0),  # left
    2: (1, 0),   # right
    3: (0, -1),  # up
    4: (0, 1),   # down
}
FAC_STR_TO_DIR = {'left': 1, 'right': 2, 'up': 3, 'down': 4}
DIR_TO_FAC_STR = {v: k for k, v in FAC_STR_TO_DIR.items()}

PASSABLE_TILES = {'grass', 'sand', 'path'}

def controller(state) -> int:
    # Local helpers
    width, height = state['size']
    game_map = state['map']
    objects = state['objects']
    player = state['player']
    px, py = player['pos']
    facing_str = player.get('facing', 'down')
    facing_dir = FAC_STR_TO_DIR.get(facing_str, 4)
    inv = player.get('inventory', {})
    daylight = state.get('daylight', 1.0)

    # quick getters
    def in_bounds(x, y):
        return 0 <= x < width and 0 <= y < height

    # set of object positions (for occupancy)
    obj_pos_set = set()
    kind_positions = {}
    for obj in objects:
        pos = obj.get('pos')
        if pos is None:
            continue
        obj_pos_set.add(tuple(pos))
        kind_positions.setdefault(obj['kind'], []).append(obj)

    def tile_at(x, y):
        return game_map[y][x]

    def is_passable(x, y):
        # player can move into grass, sand or path and it must be free (no objects)
        if not in_bounds(x, y):
            return False
        if (x, y) in obj_pos_set:
            return False
        return tile_at(x, y) in PASSABLE_TILES

    def is_free_place_tile(x, y):
        # free for placing: grass, sand or path (map must not already be table/furnace)
        if not in_bounds(x, y):
            return False
        if tile_at(x, y) not in PASSABLE_TILES:
            return False
        if (x, y) in obj_pos_set:
            return False
        return True

    # find positions of particular map tile types
    def find_tiles_of_type(tile_type):
        res = []
        for y in range(height):
            row = game_map[y]
            for x in range(width):
                if row[x] == tile_type:
                    res.append((x, y))
        return res

    # find positions for any of a set of tile types
    def find_tiles_of_types(tile_types):
        res = []
        s = set(tile_types)
        for y in range(height):
            row = game_map[y]
            for x in range(width):
                if row[x] in s:
                    res.append((x, y))
        return res

    # find object positions by kind string
    def find_objects_of_kind(kind):
        return [o for o in objects if o['kind'] == kind]

    # check map for a table or furnace (first instance)
    def find_map_item(item_name):
        for y in range(height):
            for x in range(width):
                if game_map[y][x] == item_name:
                    return (x, y)
        return None

    table_pos = find_map_item('table')
    furnace_pos = find_map_item('furnace')

    # check nearby table/furnace (3x3 area)
    def nearby_map_item(item_name):
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                nx, ny = px + dx, py + dy
                if in_bounds(nx, ny) and game_map[ny][nx] == item_name:
                    return True
        return False

    # BFS that finds a path to a position such that that position is adjacent to any of
    # the target_positions and the final move direction into that position equals facing direction
    # required to face the target. Returns tuple (path_dirs_list, target_pos, dir_to_target)
    # where path_dirs_list is list of direction ints (1..4) to execute; empty list means already in place and facing correct.
    def bfs_to_face_targets(target_positions):
        if not target_positions:
            return None
        target_set = set(target_positions)
        # helper to check adjacency and direction from pos to target
        def adj_and_dir(posx, posy, tpos):
            tx, ty = tpos
            dx = tx - posx
            dy = ty - posy
            if abs(dx) + abs(dy) != 1:
                return None
            if dx == -1:
                return 1
            if dx == 1:
                return 2
            if dy == -1:
                return 3
            if dy == 1:
                return 4
            return None

        start = (px, py)
        # quick check: if already adjacent to a target and currently facing it, accept.
        for t in target_positions:
            d = adj_and_dir(px, py, t)
            if d is not None and facing_dir == d:
                return ([], t, d)

        # BFS over positions; visited includes last_dir to ensure last movement direction matters
        visited = set()
        q = deque()
        # initial last_dir is None
        q.append((px, py, [], None))
        visited.add((px, py, None))
        while q:
            x, y, path, last_dir = q.popleft()
            # check adjacency to targets
            for t in target_positions:
                d = adj_and_dir(x, y, t)
                if d is not None:
                    # We require that the last move into (x,y) has direction equal to the direction we need to face.
                    # That ensures that the player's facing after stepping to (x,y) points to t.
                    if last_dir == d:
                        return (path, t, d)
            # expand neighbors
            for d, (dx, dy) in DIRS.items():
                nx, ny = x + dx, y + dy
                if not is_passable(nx, ny):
                    continue
                state_key = (nx, ny, d)
                if state_key in visited:
                    continue
                visited.add(state_key)
                q.append((nx, ny, path + [d], d))
        return None

    # BFS to move near a particular map item (within radius cells including diagonal) - used for tables/furnaces
    def bfs_to_get_within(target_positions, radius=1):
        if not target_positions:
            return None
        target_set = set(target_positions)
        # quick if already within radius
        def within_any(x, y):
            for tx, ty in target_positions:
                if abs(tx - x) <= radius and abs(ty - y) <= radius:
                    return True
            return False

        if within_any(px, py):
            return []
        visited = set()
        q = deque()
        q.append((px, py, []))
        visited.add((px, py))
        while q:
            x, y, path = q.popleft()
            if within_any(x, y):
                return path
            for d, (dx, dy) in DIRS.items():
                nx, ny = x + dx, y + dy
                if not is_passable(nx, ny):
                    continue
                if (nx, ny) in visited:
                    continue
                visited.add((nx, ny))
                q.append((nx, ny, path + [d]))
        return None

    # helper to convert a direction int (1..4) to action (1..4)
    def dir_to_move_action(d):
        return d  # they match by numbering

    # helper to get first move action for a path list
    def first_move_for_path(path):
        if not path:
            return None
        return dir_to_move_action(path[0])

    # helper: go to and face nearest tile type
    def go_and_face_tile_types(tile_types):
        targets = find_tiles_of_types(tile_types)
        if not targets:
            return None
        res = bfs_to_face_targets(targets)
        if res is None:
            return None
        path, tpos, dir_to_target = res
        if path:
            return first_move_for_path(path)
        else:
            # already in place and facing
            return ACTION_DO

    # helper: go to and face nearest object kind (like cow, zombie, skeleton)
    def go_and_face_object_kind(kind):
        objs = find_objects_of_kind(kind)
        if not objs:
            return None
        targets = [tuple(o['pos']) for o in objs]
        res = bfs_to_face_targets(targets)
        if res is None:
            return None
        path, tpos, dir_to_target = res
        if path:
            return first_move_for_path(path)
        else:
            return ACTION_DO

    # helper: go near map item (table/furnace) within 1 cell
    def go_near_map_item(item_name):
        pos = find_map_item(item_name)
        if not pos:
            return None
        res = bfs_to_get_within([pos], radius=1)
        if res is None:
            return None
        if res:
            return first_move_for_path(res)
        else:
            return None  # already nearby, no move needed

    # helper: go to and face a free place tile for placing (table/furnace/place_plant)
    def go_and_face_free_place():
        free_tiles = []
        for y in range(height):
            for x in range(width):
                if is_free_place_tile(x, y):
                    free_tiles.append((x, y))
        if not free_tiles:
            return None
        res = bfs_to_face_targets(free_tiles)
        if res is None:
            return None
        path, tpos, d = res
        if path:
            return first_move_for_path(path)
        else:
            return 'AT_GOAL'  # at goal and facing free cell

    # resources in inventory
    wood = inv.get('wood', 0)
    stone = inv.get('stone', 0)
    coal = inv.get('coal', 0)
    iron = inv.get('iron', 0)
    diamond = inv.get('diamond', 0)
    sapling = inv.get('sapling', 0)
    food = inv.get('food', 0)
    drink = inv.get('drink', 0)
    energy = inv.get('energy', 0)
    hp = inv.get('health', 0)
    w_pick = inv.get('wood_pickaxe', 0)
    s_pick = inv.get('stone_pickaxe', 0)
    i_pick = inv.get('iron_pickaxe', 0)
    w_sword = inv.get('wood_sword', 0)
    s_sword = inv.get('stone_sword', 0)
    i_sword = inv.get('iron_sword', 0)

    # Phase decision logic (based on earlier plan)
    # Phase 1: collect wood until wood >= 2
    if wood < 2:
        # find nearest tree and approach and do
        trees = find_tiles_of_type('tree')
        if trees:
            res = bfs_to_face_targets(trees)
            if res:
                path, tpos, d = res
                if path:
                    return dir_to_move_action(path[0])
                else:
                    return ACTION_DO
        # no trees reachable -> try exploring: random move to any nearby passable
        # choose a neighboring passable tile
        for d, (dx, dy) in DIRS.items():
            nx, ny = px + dx, py + dy
            if is_passable(nx, ny):
                return dir_to_move_action(d)
        return ACTION_NOOP

    # Phase 2: place a table if no table on map
    if table_pos is None:
        # need at least 2 wood to place table
        if wood >= 2:
            # go face a free place tile and place table
            res = bfs_to_face_targets([(x, y) for y in range(height) for x in range(width) if is_free_place_tile(x, y)])
            if res:
                path, tpos, d = res
                if path:
                    return dir_to_move_action(path[0])
                else:
                    return ACTION_PLACE_TABLE
        else:
            # fallback: collect more wood
            trees = find_tiles_of_type('tree')
            if trees:
                res = bfs_to_face_targets(trees)
                if res:
                    path, tpos, d = res
                    if path:
                        return dir_to_move_action(path[0])
                    else:
                        return ACTION_DO
        return ACTION_NOOP

    # Phase 3: make wood pickaxe and wood sword if missing
    if w_pick <= 0 or w_sword <= 0:
        # ensure table nearby
        if not nearby_map_item('table'):
            mv = go_near_map_item('table')
            if mv:
                return mv
            # maybe we're already near, continue
        # craft missing items (prefer pickaxe first)
        if w_pick <= 0:
            return ACTION_MAKE_WOOD_PICK
        if w_sword <= 0:
            return ACTION_MAKE_WOOD_SWORD

    # Phase 4: collect stone and coal (we'll target stone>=2 and coal>=1)
    stone_target = 2
    coal_target = 1
    if stone < stone_target or coal < coal_target:
        # must have wood pickaxe to mine stone and coal
        if w_pick <= 0:
            # if we don't have wood pickaxe, craft or go near table to craft
            if not nearby_map_item('table'):
                mv = go_near_map_item('table')
                if mv:
                    return mv
            return ACTION_MAKE_WOOD_PICK
        # find coal or stone depending on need; prefer coal if lacking coal
        if coal < coal_target:
            coal_tiles = find_tiles_of_type('coal')
            if coal_tiles:
                res = bfs_to_face_targets(coal_tiles)
                if res:
                    path, tpos, d = res
                    if path:
                        return dir_to_move_action(path[0])
                    else:
                        return ACTION_DO
        if stone < stone_target:
            stone_tiles = find_tiles_of_type('stone')
            if stone_tiles:
                res = bfs_to_face_targets(stone_tiles)
                if res:
                    path, tpos, d = res
                    if path:
                        return dir_to_move_action(path[0])
                    else:
                        return ACTION_DO
        # if none found, wander to look for them
        for d, (dx, dy) in DIRS.items():
            nx, ny = px + dx, py + dy
            if is_passable(nx, ny):
                return dir_to_move_action(d)
        return ACTION_NOOP

    # Phase 5: make stone pickaxe and stone sword
    if s_pick <= 0 or s_sword <= 0:
        # need table nearby
        if not nearby_map_item('table'):
            mv = go_near_map_item('table')
            if mv:
                return mv
        # craft pickaxe first
        if s_pick <= 0:
            # ensure wood and stone resources - if not, go mine stone
            if wood < 1 or stone < 1:
                # go mine stone
                stone_tiles = find_tiles_of_type('stone')
                if stone_tiles:
                    res = bfs_to_face_targets(stone_tiles)
                    if res:
                        path, tpos, d = res
                        if path:
                            return dir_to_move_action(path[0])
                        else:
                            return ACTION_DO
                # fallback move
                for d, (dx, dy) in DIRS.items():
                    nx, ny = px + dx, py + dy
                    if is_passable(nx, ny):
                        return dir_to_move_action(d)
                return ACTION_NOOP
            return ACTION_MAKE_STONE_PICK
        if s_sword <= 0:
            if wood < 1 or stone < 1:
                stone_tiles = find_tiles_of_type('stone')
                if stone_tiles:
                    res = bfs_to_face_targets(stone_tiles)
                    if res:
                        path, tpos, d = res
                        if path:
                            return dir_to_move_action(path[0])
                        else:
                            return ACTION_DO
                for d, (dx, dy) in DIRS.items():
                    nx, ny = px + dx, py + dy
                    if is_passable(nx, ny):
                        return dir_to_move_action(d)
                return ACTION_NOOP
            return ACTION_MAKE_STONE_SWORD

    # Phase 6: collect iron (need stone pickaxe to mine iron)
    if iron < 1 or stone < 4:
        # ensure we have stone pickaxe
        if s_pick <= 0:
            # get or craft stone pickaxe
            if not nearby_map_item('table'):
                mv = go_near_map_item('table')
                if mv:
                    return mv
            return ACTION_MAKE_STONE_PICK
        # mine iron if needed
        if iron < 1:
            iron_tiles = find_tiles_of_type('iron')
            if iron_tiles:
                res = bfs_to_face_targets(iron_tiles)
                if res:
                    path, tpos, d = res
                    if path:
                        return dir_to_move_action(path[0])
                    else:
                        return ACTION_DO
        # also collect extra stone to build furnace
        if stone < 4:
            stone_tiles = find_tiles_of_type('stone')
            if stone_tiles:
                res = bfs_to_face_targets(stone_tiles)
                if res:
                    path, tpos, d = res
                    if path:
                        return dir_to_move_action(path[0])
                    else:
                        return ACTION_DO
        # wander fallback
        for d, (dx, dy) in DIRS.items():
            nx, ny = px + dx, py + dy
            if is_passable(nx, ny):
                return dir_to_move_action(d)
        return ACTION_NOOP

    # Phase 7: place a furnace if not present
    if furnace_pos is None:
        if stone >= 4:
            # place furnace near table (requires a table nearby)
            if not nearby_map_item('table'):
                mv = go_near_map_item('table')
                if mv:
                    return mv
            # face a free tile and place furnace (requires table nearby)
            res = bfs_to_face_targets([(x, y) for y in range(height) for x in range(width) if is_free_place_tile(x, y)])
            if res:
                path, tpos, d = res
                if path:
                    return dir_to_move_action(path[0])
                else:
                    return ACTION_PLACE_FURNACE
        else:
            # collect stone
            stone_tiles = find_tiles_of_type('stone')
            if stone_tiles:
                res = bfs_to_face_targets(stone_tiles)
                if res:
                    path, tpos, d = res
                    if path:
                        return dir_to_move_action(path[0])
                    else:
                        return ACTION_DO
        return ACTION_NOOP

    # Phase 8: make iron pickaxe
    if i_pick <= 0:
        # need table nearby and furnace nearby
        if not nearby_map_item('table'):
            mv = go_near_map_item('table')
            if mv:
                return mv
        # ensure furnace nearby
        if not nearby_map_item('furnace'):
            mv = go_near_map_item('furnace')
            if mv:
                return mv
        # ensure resources available: wood, coal, iron
        if wood < 1 or coal < 1 or iron < 1:
            # go mine missing resources
            if coal < 1:
                coal_tiles = find_tiles_of_type('coal')
                if coal_tiles:
                    res = bfs_to_face_targets(coal_tiles)
                    if res:
                        path, tpos, d = res
                        if path:
                            return dir_to_move_action(path[0])
                        else:
                            return ACTION_DO
            if iron < 1:
                iron_tiles = find_tiles_of_type('iron')
                if iron_tiles:
                    res = bfs_to_face_targets(iron_tiles)
                    if res:
                        path, tpos, d = res
                        if path:
                            return dir_to_move_action(path[0])
                        else:
                            return ACTION_DO
            if wood < 1:
                trees = find_tiles_of_type('tree')
                if trees:
                    res = bfs_to_face_targets(trees)
                    if res:
                        path, tpos, d = res
                        if path:
                            return dir_to_move_action(path[0])
                        else:
                            return ACTION_DO
            return ACTION_NOOP
        # craft iron pickaxe
        return ACTION_MAKE_IRON_PICK

    # Phase 9: collect diamond (requires iron pickaxe to mine)
    if diamond < 1:
        if i_pick <= 0:
            # ensure we have iron pick
            if not nearby_map_item('table') or not nearby_map_item('furnace'):
                mv = go_near_map_item('table') or go_near_map_item('furnace')
                if mv:
                    return mv
            return ACTION_MAKE_IRON_PICK
        diamond_tiles = find_tiles_of_type('diamond')
        if diamond_tiles:
            res = bfs_to_face_targets(diamond_tiles)
            if res:
                path, tpos, d = res
                if path:
                    return dir_to_move_action(path[0])
                else:
                    return ACTION_DO
        # wander to search
        for d, (dx, dy) in DIRS.items():
            nx, ny = px + dx, py + dy
            if is_passable(nx, ny):
                return dir_to_move_action(d)
        return ACTION_NOOP

    # Phase 10: drink water if drink low (we consider drink==0)
    if drink <= 0:
        water_tiles = find_tiles_of_type('water')
        if water_tiles:
            res = bfs_to_face_targets(water_tiles)
            if res:
                path, tpos, d = res
                if path:
                    return dir_to_move_action(path[0])
                else:
                    return ACTION_DO
        # fallback move
        for d, (dx, dy) in DIRS.items():
            nx, ny = px + dx, py + dy
            if is_passable(nx, ny):
                return dir_to_move_action(d)
        return ACTION_NOOP

    # Phase 11: eat cows and ripe plants if food low
    if food <= 0:
        # prioritize ripe plants (instant eat)
        for obj in objects:
            if obj['kind'] == 'plant' and obj.get('ripe'):
                # go and face plant to eat
                tgt = tuple(obj['pos'])
                res = bfs_to_face_targets([tgt])
                if res:
                    path, tpos, d = res
                    if path:
                        return dir_to_move_action(path[0])
                    else:
                        return ACTION_DO
        # otherwise attack cows to obtain food
        cows = find_objects_of_kind('cow')
        if cows:
            targets = [tuple(c['pos']) for c in cows]
            res = bfs_to_face_targets(targets)
            if res:
                path, tpos, d = res
                if path:
                    return dir_to_move_action(path[0])
                else:
                    return ACTION_DO
        # wander
        for d, (dx, dy) in DIRS.items():
            nx, ny = px + dx, py + dy
            if is_passable(nx, ny):
                return dir_to_move_action(d)
        return ACTION_NOOP

    # Phase 12: collect saplings (sapling <1)
    if sapling <= 0:
        # do on grass to get sapling chance
        grass_tiles = find_tiles_of_type('grass')
        if grass_tiles:
            # choose nearest grass
            res = bfs_to_face_targets(grass_tiles)
            if res:
                path, tpos, d = res
                if path:
                    return dir_to_move_action(path[0])
                else:
                    return ACTION_DO
        # move around
        for d, (dx, dy) in DIRS.items():
            nx, ny = px + dx, py + dy
            if is_passable(nx, ny):
                return dir_to_move_action(d)
        return ACTION_NOOP

    # Phase 13: place saplings if have any and there's a grass tile to place onto
    if sapling > 0:
        # place_plant requires sapling and grass in front and facing; find a grass tile that is free
        grass_tiles = []
        for y in range(height):
            for x in range(width):
                if game_map[y][x] == 'grass' and (x, y) not in obj_pos_set:
                    grass_tiles.append((x, y))
        if grass_tiles:
            res = bfs_to_face_targets(grass_tiles)
            if res:
                path, tpos, d = res
                if path:
                    return dir_to_move_action(path[0])
                else:
                    return ACTION_PLACE_PLANT
        # else wander
        for d, (dx, dy) in DIRS.items():
            nx, ny = px + dx, py + dy
            if is_passable(nx, ny):
                return dir_to_move_action(d)
        return ACTION_NOOP

    # Phase 14: sleep if energy low (<30) and safe (no zombies nearby)
    if energy < 30 and not player.get('sleeping', False):
        # check safety: no zombies within radius 3
        safe = True
        for obj in objects:
            if obj['kind'] == 'zombie':
                ox, oy = obj['pos']
                if abs(ox - px) + abs(oy - py) <= 3:
                    safe = False
                    break
        if safe:
            return ACTION_SLEEP
        else:
            # try to move away from nearest zombie
            zombies = find_objects_of_kind('zombie')
            if zombies:
                zx, zy = zombies[0]['pos']
                # move in opposite direction if possible
                dx = px - zx
                dy = py - zy
                if abs(dx) >= abs(dy):
                    if dx > 0 and is_passable(px + 1, py):
                        return ACTION_RIGHT
                    if dx < 0 and is_passable(px - 1, py):
                        return ACTION_LEFT
                if dy > 0 and is_passable(px, py + 1):
                    return ACTION_DOWN
                if dy < 0 and is_passable(px, py - 1):
                    return ACTION_UP
            # fallback noop
            return ACTION_NOOP

    # Phase 15: defeat zombies and skeletons if any exist
    zombies = find_objects_of_kind('zombie')
    skeletons = find_objects_of_kind('skeleton')
    monsters = zombies + skeletons
    if monsters:
        # target nearest monster
        monsters_pos = [tuple(m['pos']) for m in monsters]
        res = bfs_to_face_targets(monsters_pos)
        if res:
            path, tpos, d = res
            if path:
                return dir_to_move_action(path[0])
            else:
                # if we have a sword prefer to use it (just do action; game will use sword if available)
                return ACTION_DO
        # fallback wander
        for d, (dx, dy) in DIRS.items():
            nx, ny = px + dx, py + dy
