            if mon:
                ox, oy = mon['pos']
                dx = px - ox
                dy = py - oy
                if abs(dx) >= abs(dy):
                    if dx > 0 and is_passable(px + 1, py):
                        return ACTION_RIGHT
                    if dx < 0 and is_passable(px - 1, py):
                        return ACTION_LEFT
                if dy > 0 and is_passable(px, py + 1):
                    return ACTION_DOWN
                if dy < 0 and is_passable(px, py - 1):
                    return ACTION_UP
            return ACTION_NOOP

    # Keep near base for safety but avoid sleeping as idle:
    if table_pos and nearby_map_item('table'):
        # recover by performing useful tasks (crafting) rather than sleeping
        # If any craftable items missing that improve survival, craft:
        if s_sword <= 0 and wood >= 1 and stone >= 1 and nearby_map_item('table'):
            return ACTION_MAKE_STONE_SWORD
        if i_sword <= 0 and wood >= 1 and coal >= 1 and iron >= 1 and nearby_map_item('table') and nearby_map_item('furnace'):
            return ACTION_MAKE_IRON_SWORD
        # if food/drink low, fetch them (handled earlier)
        return ACTION_NOOP

    # Move to table if base exists (safer)
    if table_pos:
        mv = go_near_map_item('table')
        if mv:
            return mv

    # Final goal-driven move: head toward remaining important resources
    goals = []
    if drink < PREFERRED_DRINK:
        goals += find_tiles_of_type('water')
    if food < PREFERRED_FOOD:
        goals += [tuple(o['pos']) for o in objects if o['kind'] in ('cow',) or (o['kind'] == 'plant' and o.get('ripe'))]
    if coal < 2:
        goals += find_tiles_of_type('coal')
    if iron < 1:
        goals += find_tiles_of_type('iron')
    if diamond < 1:
        goals += find_tiles_of_type('diamond')
    if not goals:
        return ACTION_NOOP

    best_dir = None
    best_dist = None
    for d, (dx, dy) in DIRS.items():
        nx, ny = px + dx, py + dy
        if not is_passable(nx, ny):
            continue
        md = min((abs(gx - nx) + abs(gy - ny)) for gx, gy in goals)
        if best_dist is None or md < best_dist:
            best_dist = md
            best_dir = d
    if best_dir:
        return dir_to_move_action(best_dir)

    return ACTION_NOOP
